const i = $input.first().json;
const pick = (...keys) => {
  for (const k of keys) if (i[k] !== undefined && i[k] !== null && i[k] !== '') return i[k];
  return null;
};
const num = v => (v === null || isNaN(Number(v)) ? null : Number(v));

const input = {
  source: i.source || 'form',
  test_id: i.test_id || null,
  force_bad_citation: i.force_bad_citation === true,
  language: pick('Preferred language', 'language'),
  story: pick('Your story', 'story'),
  contract_text: pick('Contract text (optional)', 'contract_text'),
  basic_salary: num(pick('Basic monthly salary (AED)', 'basic_salary')),
  total_salary: num(pick('Total monthly salary (AED)', 'total_salary')),
  start_date: pick('Start date', 'start_date'),
  end_date: pick('End date (if you left)', 'end_date'),
  emirate: pick('Emirate', 'emirate'),
  work_location: pick('Where do you work?', 'work_location'),
  email: pick('Email (optional)', 'email'),
};

return [{ json: { input, started_at: new Date().toISOString() } }];

function parseK2(resp) {
  let text = resp?.choices?.[0]?.message?.content ?? '';
  text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
  text = text.replace(/```json|```/g, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) {
    throw new Error('K2 did not return JSON. First 300 chars: ' + text.slice(0, 300));
  }
  return JSON.parse(text.slice(start, end + 1));
}

const c = $('Build Intake Prompt').first().json.case;
const intake = parseK2($input.first().json);

// Form choice about workplace overrides the model if clearly stated
const wl = (c.input.work_location || '').toLowerCase();
if (wl.includes('free zone')) { intake.work_location = 'free_zone'; intake.in_scope = false; }
if (wl.includes('household')) { intake.work_location = 'domestic'; intake.in_scope = false; }

// Facts we cannot analyse without
const critical_missing = [];
if (!intake.basic_salary && !intake.total_salary) critical_missing.push('Your monthly salary in AED');
if (!intake.start_date) critical_missing.push('The date you started this job');
if (!intake.issue_types || intake.issue_types.length === 0) intake.issue_types = ['other'];

return [{ json: { ...c, intake, critical_missing } }];

// VERIFY every value against the official text in the Law Pack before the demo.
const CONFIG = {
  GRATUITY_MIN_YEARS: 1,            // minimum service for gratuity (Art. 51(2))
  GRATUITY_DAYS_FIRST_5_YEARS: 21,  // days of basic wage per year, first 5 years (Art. 51(2)(a))
  GRATUITY_DAYS_AFTER_5_YEARS: 30,  // days of basic wage per year after 5 years (Art. 51(2)(b))
  GRATUITY_CAP_YEARS_OF_WAGE: 2,    // cap, in years of basic wage (Art. 51(6))
  DAYS_IN_MONTH_FOR_DAILY_WAGE: 30, // how a daily wage is derived
  MOHRE_DECISION_LIMIT_AED: 50000   // above this, unresolved claims go to court (Art. 54(2))
};

const c = $input.first().json;
const f = c.intake;
const round = n => Math.round(n * 100) / 100;

const basic = f.basic_salary ?? f.total_salary;
const total = f.total_salary ?? f.basic_salary;
const start = new Date(f.start_date);
const end = f.end_date ? new Date(f.end_date) : new Date();
const years = Math.max(0, (end - start) / (365.25 * 24 * 3600 * 1000));
const dailyBasic = basic / CONFIG.DAYS_IN_MONTH_FOR_DAILY_WAGE;
const dailyTotal = total / CONFIG.DAYS_IN_MONTH_FOR_DAILY_WAGE;

// Gratuity (only if the job has ended)
const jobEnded = f.termination_type === 'employer_terminated' || f.termination_type === 'resigned';
let gratuity = { applicable: jobEnded, eligible: false, amount: 0, formula: 'Not calculated: job has not ended' };
if (jobEnded) {
  if (years >= CONFIG.GRATUITY_MIN_YEARS) {
    const first = Math.min(years, 5), rest = Math.max(years - 5, 0);
    const days = first * CONFIG.GRATUITY_DAYS_FIRST_5_YEARS + rest * CONFIG.GRATUITY_DAYS_AFTER_5_YEARS;
    const cap = basic * 12 * CONFIG.GRATUITY_CAP_YEARS_OF_WAGE;
    const amount = Math.min(days * dailyBasic, cap);
    gratuity = { applicable: true, eligible: true, amount: round(amount),
      formula: `${round(first)} yrs x ${CONFIG.GRATUITY_DAYS_FIRST_5_YEARS} days + ${round(rest)} yrs x ${CONFIG.GRATUITY_DAYS_AFTER_5_YEARS} days = ${round(days)} days x AED ${round(dailyBasic)} basic daily wage${amount === cap ? ' (capped)' : ''}` };
  } else {
    gratuity = { applicable: true, eligible: false, amount: 0, formula: `Service ${round(years)} yrs is below ${CONFIG.GRATUITY_MIN_YEARS} yr minimum` };
  }
}

// Unpaid wages
const months = f.unpaid_months || 0;
const unpaid = { months, amount: round(months * total), formula: `${months} months x AED ${total} total monthly wage` };

// Notice pay (only if the employer ended the job)
const shortDays = Math.max((f.notice_days_contract || 0) - (f.notice_days_given || 0), 0);
const notice = f.termination_type === 'employer_terminated'
  ? { shortfall_days: shortDays, amount: round(shortDays * dailyTotal), formula: `${shortDays} days x AED ${round(dailyTotal)} total daily wage` }
  : { shortfall_days: 0, amount: 0, formula: 'Not applicable' };

// Deductions reported by the worker
const deductions = { amount: round(f.deducted_amount_total || 0), formula: 'Total amount the worker reports was deducted' };

const total_claim = round(gratuity.amount + unpaid.amount + notice.amount + deductions.amount);

const calc = {
  service_years: round(years), basic_monthly: basic, total_monthly: total,
  gratuity, unpaid_wages: unpaid, notice_pay: notice, deductions,
  total_claim, above_mohre_limit: total_claim > CONFIG.MOHRE_DECISION_LIMIT_AED,
  config_used: CONFIG
};

return [{ json: { ...c, calc } }];

function parseK2(resp) {
  let text = resp?.choices?.[0]?.message?.content ?? '';
  text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
  text = text.replace(/```json|```/g, '').trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) {
    throw new Error('K2 did not return JSON. First 300 chars: ' + text.slice(0, 300));
  }
  return JSON.parse(text.slice(start, end + 1));
}

function enforceCitations(a, law) {
  const valid = new Set(law.map(x => x.id));
  a.not_covered = a.not_covered || [];
  a.issues = (a.issues || []).filter(i => {
    i.article_ids = (i.article_ids || []).filter(id => valid.has(id));
    if (i.article_ids.length === 0) { a.not_covered.push(i.finding); return false; }
    return true;
  });
  return a;
}

const c = $('Build Analyst Prompt').first().json.case;
const analysis = parseK2($input.first().json);

enforceCitations(analysis, c.law);

// TEST ONLY (TC-11): seed a real but wrong citation so the Critic must catch it
if (c.input.source === 'test' && c.input.force_bad_citation && analysis.issues.length) {
  analysis.issues[0].article_ids = ['TIME_LIMIT'];
}

return [{ json: { ...c, analysis } }];

const c = $input.first().json;

const system = `You are the Critic Agent for Haqqi. Your job is to find mistakes in the Analyst's work.
Check the ANALYSIS against FACTS, LAW and CALC:
1. Does each cited article's text actually support its finding? If not, that is a problem.
2. Is any finding not supported by the facts?
3. Did the Analyst miss an issue the facts clearly raise and LAW covers?
4. Do the claims match CALC (include only amounts that CALC computed and that apply)?
5. Is anything stated as law that is not in LAW?
Be strict but fair. If there are no real problems, verdict is pass.

Return ONLY this JSON:
{"verdict": "pass"|"revise", "problems": [{"where": string, "problem": string, "fix": string}], "missed_issues": [string]}`;

const lawText = c.law.map(a => ({ id: a.id, ref: a.ref, text: a.text_en }));
const user = [
  'FACTS:\n' + JSON.stringify(c.intake, null, 2),
  'LAW:\n' + JSON.stringify(lawText, null, 2),
  'CALC:\n' + JSON.stringify(c.calc, null, 2),
  'ANALYSIS:\n' + JSON.stringify(c.analysis, null, 2)
].join('\n\n');

return [{ json: { case: c, body: { model: 'IFM/K2-Horizon-375B-A23B', messages: [
  { role: 'system', content: system }, { role: 'user', content: user } ] } } }];

