const c = $('Build Critic Prompt').first().json.case;
const critic = parseK2($input.first().json);
if (critic.verdict !== 'pass') critic.verdict = 'revise';

return [{ json: {
  ...c,
  critic,
  revised: false,
  final_analysis: critic.verdict === 'pass' ? c.analysis : null
}}];

const c = $input.first().json;
const analystRules = $('Build Analyst Prompt').first().json.body.messages[0].content;

const system = analystRules + `

You are now REVISING your earlier analysis. Fix every problem the Critic raised.
Add any missed issue only if LAW covers it. Return the full corrected JSON in the same format.`;

const lawText = c.law.map(a => ({ id: a.id, ref: a.ref, topic: a.topic, text: a.text_en }));
const user = [
  'FACTS:\n' + JSON.stringify(c.intake, null, 2),
  'LAW:\n' + JSON.stringify(lawText, null, 2),
  'CALC:\n' + JSON.stringify(c.calc, null, 2),
  'YOUR EARLIER ANALYSIS:\n' + JSON.stringify(c.analysis, null, 2),
  'CRITIC FEEDBACK:\n' + JSON.stringify(c.critic, null, 2)
].join('\n\n');

return [{ json: { case: c, body: { model: 'IFM/K2-Horizon-375B-A23B', messages: [
  { role: 'system', content: system }, { role: 'user', content: user } ] } } }];

