const c = $('Build Writer Prompt').first().json.case;
const writer = parseK2($input.first().json);
if (!/[؀-ۿ]/.test(writer.arabic_letter || '')) {
  throw new Error('Writer did not return an Arabic letter');
}

return [{ json: { ...c, writer } }];

const c = $input.first().json;
const w = c.writer, a = c.final_analysis, k = c.calc;
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

const DISCLAIMER = 'Haqqi gives guidance and a draft, not legal advice. For official help, contact MoHRE on 80084 or use the MoHRE app or website.';
const DISCLAIMER_AR = 'يقدم حقّي إرشادات ومسودة فقط، وليس استشارة قانونية. للمساعدة الرسمية تواصل مع وزارة الموارد البشرية والتوطين على الرقم 80084.';

const list = arr => '<ul>' + (arr || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ul>';

const citations = (a.issues || []).map(i => {
  const refs = i.article_ids.map(id => (c.law.find(l => l.id === id) || {}).ref).join(', ');
  return `${i.type}: ${refs}`;
});

const page_html = `
<h2>${esc(w.headline)}</h2>
<p>${esc(w.explanation)}</p>
<h3>Money you may be owed</h3>${list(w.amount_lines)}
<p><b>Estimated total: AED ${esc(k.total_claim)}</b>${k.above_mohre_limit ? ' (above AED 50,000: if not settled, this may go to court)' : ''}</p>
<h3>What to do next</h3>${list(w.checklist)}
<h3>Documents to gather</h3>${list(a.documents_to_gather)}
<h3>Law used</h3>${list(citations)}
<h3>Complaint draft (Arabic)</h3>
<div dir="rtl" lang="ar" style="white-space:pre-wrap;text-align:right">${esc(w.arabic_letter)}</div>
<hr><p><small>${esc(DISCLAIMER)}</small></p>
<p dir="rtl" lang="ar"><small>${esc(DISCLAIMER_AR)}</small></p>`;

const stats = {
  timestamp: new Date().toISOString(),
  outcome: 'case_pack',
  issue_types: (c.intake.issue_types || []).join(', '),
  emirate: c.input.emirate,
  language: c.intake.language_name,
  critic_verdict: c.critic.verdict,
  revised: c.revised,
  duration_sec: Math.round((Date.now() - new Date(c.started_at)) / 1000),
